const KEY='sever-data-v2',ANONYMOUS_KEY='sever-anonymous-state-v1',LEGACY_OWNER_KEY='sever-cloud-legacy-owner-v1',months=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
