function renderChallenge(){const categories=challengeCategories(),block=$('#challengeBlock');block.classList.toggle('hidden',!categories.length);if(!categories.length)return;const days=state.challengeDays||30;$('#challengeTitle').textContent=state.challengeName||categories.join(' + ');const elapsed=Math.floor((dateOf(TODAY)-dateOf(state.challengeStart))/86400000)+1;$('#dayCounter').textContent=`День ${Math.min(days,Math.max(1,elapsed))}/${days}`;const root=$('#challengeProgress');root.innerHTML='';categories.forEach(category=>{const list=challengeTasks(category),done=list.filter(t=>t.completed).length,card=document.createElement('article');card.innerHTML=`<div><span></span><b>${done}/${list.length}</b></div><i><em style="width:${list.length?done/list.length*100:0}%"></em></i>`;card.querySelector('span').textContent=category;root.appendChild(card)})}

