function renderCalendar(){const y=cursor.getFullYear(),m=cursor.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7;$('#monthTitle').textContent=`${months[m]} ${y}`;const root=$('#calendar');root.innerHTML='';for(let i=0;i<42;i++){const d=new Date(y,m,i-offset+1),key=dayISO(d),items=state.tasks.filter(t=>t.date===key),b=document.createElement('button');b.className='day'+(d.getMonth()!==m?' dim':'')+(key===TODAY?' today':'');b.setAttribute('aria-label',`${pretty(key,false)}, задач: ${items.length}`);b.innerHTML=`<span>${d.getDate()}</span>${items.slice(0,3).map(t=>`<u>${t.completed?'✓ ':''}${escapeText(t.title)}</u>`).join('')}`;b.onclick=()=>openDay(key);root.appendChild(b)}}
