function focusTimeLabel(ms){if(ms>0&&ms<60000)return'<1 мин';return Math.floor(ms/60000)+' мин'}
function renderProgress(){const completed=state.tasks.filter(t=>t.completed),planned=completed.reduce((a,t)=>a+(Number(t.duration)||0),0);$('#allDone').textContent=completed.length;$('#streak').textContent=streak()+' дней';$('#focusMinutes').textContent=focusTimeLabel(state.stats.focusMs);$('#focusSessions').textContent=state.stats.sessions+' сессий';$('#plannedMinutes').textContent=planned+' мин';const root=$('#heatmap'),hasChallenge=state.tasks.some(t=>t.challenge),span=Math.min(hasChallenge?(state.challengeDays||30):30,60),start=hasChallenge?state.challengeStart:addDays(TODAY,-29);root.innerHTML='';for(let i=0;i<span;i++){const date=addDays(start,i),list=state.tasks.filter(t=>t.date===date&&(!hasChallenge||t.challenge)),done=list.filter(t=>t.completed).length,el=document.createElement('div');el.className='heat '+(list.length&&done===list.length?'full':done?'half':'');el.title=`${pretty(date,false)}: ${done}/${list.length}`;el.textContent=i+1;root.appendChild(el)}const from=addDays(TODAY,-6),week=state.tasks.filter(t=>t.date>=from&&t.date<=TODAY),done=week.filter(t=>t.completed).length,total=week.length,p=total?Math.round(done/total*100):0;$('#reviewTitle').textContent=`${done} из ${total} задач · ${p}%`;$('#reviewText').textContent=p>=80?'Ты уверенно держишь курс. Сохраняй такой темп.':p>=50?'Хорошее движение. На следующей неделе выбери три главных шага заранее.':'Сделай план легче: оставь одну небольшую обязательную задачу на день.'}
const habitWeekLabels=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
function habitWeekStart(){return addDays(TODAY,-((dateOf(TODAY).getDay()+6)%7))}
function toggleHabitCheck(habitId,date=TODAY){const habit=state.habits.find(item=>item.id===habitId);if(!habit)return;if(date>TODAY){toast('Будущие дни можно отметить позже');return}const checks=state.checks[habitId]??[],wasCompleted=checks.includes(date);state.checks[habitId]=wasCompleted?checks.filter(item=>item!==date):[...checks,date];save();render();const dayLabel=date===TODAY?'сегодня':pretty(date,false);toast(wasCompleted?`Отметка за ${dayLabel} снята`:`Отмечено: ${dayLabel}`,()=>{state.checks[habitId]=wasCompleted?[...checks]:checks.filter(item=>item!==date);save();render()})}
